"use client"

import * as React from "react"
import { accentChain } from "glimm"
import { GlimmScope, type GlimmScopeHandle } from "glimm/react"

const palette = accentChain(["#00C0E8", "#0088FF", "#6155F5", "#CB30E0"])
const ink = "#242529"
const line = "#ececee"

function Skeleton({ width, height = 9, radius = 6 }: { width: number | string; height?: number; radius?: number }) {
  return <span aria-hidden="true" style={{ background: "#efeff0", borderRadius: radius, display: "block", height, width }} />
}

function Dashboard({ pro }: { pro: boolean }) {
  return (
    <div style={{ display: "flex", height: "100%", minHeight: 560 }}>
      <aside style={{ borderRight: `1px solid ${line}`, display: "flex", flexDirection: "column", gap: 22, padding: "18px 14px", width: 204 }}>
        <div style={{ alignItems: "center", display: "flex", gap: 8 }}><Skeleton height={26} radius={8} width={26} /><Skeleton width={84} /></div>
        {[1, 2].map((group) => <div key={group} style={{ display: "grid", gap: 12 }}><Skeleton height={8} width={48} />{[92, 70, 104, 60].map((w) => <div key={w} style={{ alignItems: "center", display: "flex", gap: 12 }}><Skeleton height={16} radius={5} width={16} /><Skeleton width={w} /></div>)}</div>)}
        <div style={{ alignItems: "center", display: "flex", gap: 10, marginTop: "auto" }}><Skeleton height={28} radius={999} width={28} /><Skeleton width={96} /></div>
      </aside>
      <div style={{ flex: 1, minWidth: 0 }}>
        <header style={{ alignItems: "center", borderBottom: `1px solid ${line}`, display: "flex", height: 56, justifyContent: "space-between", padding: "0 24px" }}><Skeleton height={30} radius={8} width="38%" /><div style={{ display: "flex", gap: 12 }}><Skeleton height={30} radius={8} width={30} /><Skeleton height={30} radius={999} width={30} /></div></header>
        <div style={{ color: ink, maxWidth: 880, padding: "32px 36px" }}>
          <Skeleton height={20} radius={7} width={150} /><div style={{ height: 12 }} /><Skeleton width={260} />
          <section style={{ background: "#fff", borderRadius: 16, marginTop: 28, padding: 16 }}>
            <div style={{ alignItems: "flex-start", display: "flex", justifyContent: "space-between" }}>
              <div style={{ display: "grid", gap: 8 }}><Skeleton height={8} width={80} /><div style={{ alignItems: "center", display: "flex", gap: 8 }}><span style={{ fontSize: 16 }}>{pro ? "Pro" : "Free"}</span>{pro && <span aria-label="Active" style={{ background: "#ebf7ee", borderRadius: 999, color: "#4a9c61", fontSize: 10, padding: "3px 7px" }}>Active</span>}</div><Skeleton width={pro ? 168 : 120} /></div>
              <Skeleton height={34} radius={999} width={120} />
            </div>
            <div style={{ borderTop: `1px solid ${line}`, display: "grid", gap: 16, gridTemplateColumns: "repeat(3,1fr)", marginTop: 16, paddingTop: 16 }}>{[6, 10, 2].map((v, i) => <div key={i} style={{ background: "#f0f0f1", borderRadius: 99, height: 6 }}><div style={{ background: "#cdcdcf", borderRadius: 99, height: "100%", width: pro ? `${v}%` : i === 2 ? "94%" : "100%" }} /></div>)}</div>
          </section>
          <section style={{ background: "#fff", borderRadius: 16, display: "grid", gridTemplateColumns: "1fr 1fr", marginTop: 12, padding: "8px 16px" }}>{[108, 92, 124, 100].map((w) => <div key={w} style={{ alignItems: "center", display: "flex", gap: 12, height: 44 }}><span style={{ color: "#aaa", fontSize: 16 }}>{pro ? "✓" : "●"}</span><Skeleton width={w} /></div>)}</section>
          <section style={{ background: "#fff", borderRadius: 16, marginTop: 12, overflow: "hidden" }}>{[120, 104, 132, 96].map((w, i) => <div key={w} style={{ alignItems: "center", borderTop: i ? `1px solid ${line}` : undefined, display: "flex", gap: 16, height: 52, padding: "0 20px" }}><Skeleton width={w} /><span style={{ flex: 1 }} /><Skeleton width={56} /><Skeleton height={20} radius={6} width={20} /></div>)}</section>
        </div>
      </div>
    </div>
  )
}

function UpgradeScene() {
  const scope = React.useRef<GlimmScopeHandle>(null)
  const [pro, setPro] = React.useState(false)
  const [open, setOpen] = React.useState(true)
  const [busy, setBusy] = React.useState(false)

  const upgrade = () => {
    if (busy) return
    setBusy(true)
    scope.current?.play({
      work: () => new Promise((resolve) => window.setTimeout(resolve, 1100)),
      change: () => { setPro(true); setOpen(false) },
      onBurst: () => setBusy(false),
    })
  }

  return (
    <GlimmScope ref={scope} palette={palette} origin={[0.5, 0.5]} sweepMs={2700} style={{ inset: 0, position: "absolute" }}>
      <div style={{ background: "#f8f8f8", color: ink, fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", height: "100%", overflow: "hidden" }}>
        <Dashboard pro={pro} />
        {open && <div style={{ alignItems: "center", background: "rgba(24,24,27,.14)", display: "flex", inset: 0, justifyContent: "center", position: "absolute", zIndex: 5 }}>
          <div role="dialog" aria-label="Upgrade to Pro" style={{ background: "linear-gradient(180deg,#e9f2ff 0%,#f4f8ff 14%,#fff 30%)", borderRadius: 26, boxShadow: "0 24px 48px -8px rgba(0,0,0,.18)", overflow: "hidden", width: "min(368px,calc(100% - 32px))" }}>
            <div style={{ padding: 16 }}><div style={{ alignItems: "center", display: "flex", justifyContent: "space-between" }}><h2 style={{ fontSize: 16, fontWeight: 450, margin: 0 }}>Upgrade to Pro</h2><button aria-label="Close" onClick={() => setOpen(false)} style={{ background: "transparent", border: 0, color: "#aaa", fontSize: 20 }}>×</button></div><div style={{ display: "grid", gap: 8, marginTop: 14 }}><Skeleton height={10} width="92%" /><Skeleton height={10} width="64%" /></div><div style={{ display: "grid", gap: 12, marginTop: 24 }}>{[72, 56, 80].map((w) => <div key={w} style={{ alignItems: "center", display: "flex", gap: 12 }}><Skeleton height={16} radius={999} width={16} /><Skeleton height={10} width={`${w}%`} /></div>)}</div></div>
            <div style={{ alignItems: "center", borderTop: `1px solid ${line}`, display: "flex", justifyContent: "space-between", padding: 16 }}><div><span style={{ fontSize: 18 }}>$12</span><span style={{ color: "#8f8f94", fontSize: 13 }}> / month</span></div><button disabled={busy} onClick={upgrade} style={{ alignItems: "center", background: "#4e91f7", border: 0, borderRadius: 999, boxShadow: "0 4px 10px rgba(38,112,230,.28)", color: "#fff", display: "flex", fontSize: 14, gap: 8, height: 38, padding: "0 16px" }}><span>{busy ? "◌" : "↑"}</span>{busy ? "Upgrading" : "Upgrade"}</button></div>
          </div>
        </div>}
      </div>
    </GlimmScope>
  )
}

export default function GlimmUpgradeToPro() { return <UpgradeScene /> }
export { GlimmUpgradeToPro }
